package com.pointverse.app;
import android.test.InstrumentationTestCase;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;
@SuppressWarnings("deprecation")
public final class CloudSyncTest extends InstrumentationTestCase {
 PointStore a,b;String an,bn;Fake remote;
 static final class Fake implements CloudSync.Remote {
  Map<String,byte[]> blobs=new HashMap<>(),manifests=new HashMap<>();JSONArray versions=new JSONArray();int uploads,downloads;boolean corrupt;int failHeads;boolean loseCommit;Runnable afterDownload;
  JSONObject commit(JSONObject m)throws Exception {byte[] raw=m.toString().getBytes(StandardCharsets.UTF_8);String hash=CloudSync.hash(raw);if(manifests.containsKey(hash)){for(int i=0;i<versions.length();i++)if(hash.equals(versions.getJSONObject(i).getString("manifest_hash")))return versions.getJSONObject(i);}manifests.put(hash,raw);JSONObject v=new JSONObject().put("point_id",m.getString("point_id")).put("manifest_hash",hash).put("revision",m.getInt("revision")).put("title",m.optString("title")).put("preview",m.optString("preview"));JSONArray next=new JSONArray().put(v);for(int i=0;i<versions.length();i++)next.put(versions.get(i));versions=next;return v;}
  public JSONObject json(String path,String method,String token,JSONObject body)throws Exception {if(method.equals("HEAD")){if(failHeads-->0)throw new NetworkModel.ServiceException(502,"temporary","temporary");if(!blobs.containsKey(path.substring(path.lastIndexOf('/')+1)))throw new NetworkModel.ServiceException(404,"not_found","missing");return new JSONObject();}if(method.equals("POST")){JSONObject committed=commit(body);if(loseCommit){loseCommit=false;throw new NetworkModel.ServiceException(502,"temporary","temporary");}return committed;}return new JSONObject().put("items",versions).put("next_cursor","");}
  public void upload(String token,String hash,File file)throws Exception{uploads++;blobs.put(hash,Files.readAllBytes(file.toPath()));}
  public void download(String path,String token,File file,long max,String hash,long bytes)throws Exception{downloads++;byte[] data=path.contains("/assets/")?blobs.get(hash):manifests.get(hash);if(data==null)throw new IOException("missing");data=data.clone();if(corrupt&&path.contains("/assets/"))data[0]^=1;if(data.length>max)throw new IOException("too large");Files.write(file.toPath(),data);if(afterDownload!=null)afterDownload.run();}
 }
 protected void setUp()throws Exception {super.setUp();an="sync-a-"+UUID.randomUUID()+".db";bn="sync-b-"+UUID.randomUUID()+".db";a=new PointStore(getInstrumentation().getTargetContext(),an);b=new PointStore(getInstrumentation().getTargetContext(),bn);remote=new Fake();}
 protected void tearDown()throws Exception {for(PointStore s:new PointStore[]{a,b}){File media=s.audio.getParentFile();s.close();PointStore.removeTree(media);}getInstrumentation().getTargetContext().deleteDatabase(an);getInstrumentation().getTargetContext().deleteDatabase(bn);super.tearDown();}
 String audio()throws Exception {File file=a.newRecording();try(InputStream in=getInstrumentation().getContext().getAssets().open("tone.m4a");OutputStream out=new FileOutputStream(file)){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);}a.commitAudio(file);String id=file.getName().replace(".m4a","");a.addCandidate(id,"cloud","识别出的原始语音");return id;}
 JSONObject latest(){return remote.versions.optJSONObject(0);}
 CloudSync from(PointStore s){return new CloudSync(s,remote);}
 public void testTextRoundTripPreservesEditsFacetsSummaryAndConversation()throws Exception {String id=a.createText("我的标题","完整原文");a.field(id,"domain","科学");a.field(id,"summary","摘要");a.field(id,"speaker","本人");a.message(id,"assistant","继续思考的回复","model");assertTrue(from(a).upload(a.get(id),"account","token"));CloudRestore.Result result=from(b).download(latest(),"account","token");assertEquals("added",result.kind);PointStore.Point p=b.get(id);assertEquals("完整原文",p.body);assertEquals("我的标题",p.title);assertEquals("科学",p.domain);assertEquals("摘要",p.summary);assertEquals("本人",p.speaker);assertEquals("继续思考的回复",b.rows("conversation",id).getJSONObject(0).getString("text"));}
 public void testAudioPhotoAndManifestationRoundTrip()throws Exception {String id=audio();a.update(id,"手工标题","修正后的转写");android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(20,20,android.graphics.Bitmap.Config.ARGB_8888);ByteArrayOutputStream bytes=new ByteArrayOutputStream();image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,bytes);image.recycle();a.addImage(id,bytes.toByteArray(),"test-image");String imageID=a.rows("images",id).getJSONObject(0).getString("id");a.imageCaption(imageID,"人工照片说明");a.saveManifestation(a.get(id),"image",imageID,"image-model","dream");from(a).upload(a.get(id),"account","token");from(b).download(latest(),"account","token");PointStore.Point point=b.get(id);assertEquals("修正后的转写",point.effective());assertEquals("识别出的原始语音",point.machine);assertEquals("手工标题",point.title);assertEquals(LocalSpeech.hash(a.audioFile(a.get(id))),LocalSpeech.hash(b.audioFile(point)));assertEquals("人工照片说明",b.rows("images",id).getJSONObject(0).getString("caption"));assertEquals(imageID,b.rows("manifestations",id).getJSONObject(0).getString("content"));assertEquals("dream",b.rows("manifestations",id).getJSONObject(0).getString("lens"));}
 public void testRepeatedTransferIsIdempotentAndSkipsUploadedAssets()throws Exception {String id=audio();from(a).upload(a.get(id),"account","token");int uploads=remote.uploads;assertFalse(from(a).upload(a.get(id),"account","token"));assertEquals(uploads,remote.uploads);from(b).download(latest(),"account","token");int downloads=remote.downloads;assertEquals("skipped",from(b).download(latest(),"account","token").kind);assertEquals(downloads,remote.downloads);assertEquals(1,b.list("").size());}
 public void testCloudUpdateReplacesOnlyUnchangedLocalVersion()throws Exception {String id=a.createText("标题","第一版");from(a).upload(a.get(id),"account","token");from(b).download(latest(),"account","token");a.update(id,"标题","云端新版");from(a).upload(a.get(id),"account","token");assertEquals("updated",from(b).download(latest(),"account","token").kind);assertEquals("云端新版",b.get(id).body);assertEquals(1,b.list("").size());}
 public void testConcurrentEditsKeepBothVersionsWithoutRepeatedCopies()throws Exception {String id=a.createText("标题","初始");from(a).upload(a.get(id),"account","token");from(b).download(latest(),"account","token");b.update(id,"本机标题","本机修改");a.update(id,"云端标题","云端修改");from(a).upload(a.get(id),"account","token");CloudRestore.Result r=from(b).download(latest(),"account","token");assertEquals("conflict",r.kind);assertFalse(id.equals(r.id));assertEquals("本机修改",b.get(id).body);assertEquals("云端修改",b.get(r.id).body);assertEquals("skipped",from(b).download(latest(),"account","token").kind);assertEquals(2,b.list("").size());}
 public void testDeletedOrTrashedPointsAreNotResurrected()throws Exception {String id=a.createText("标题","初始");from(a).upload(a.get(id),"account","token");from(b).download(latest(),"account","token");b.trash(id,true);a.update(id,"标题","新版");from(a).upload(a.get(id),"account","token");assertEquals("deleted",from(b).download(latest(),"account","token").kind);b.purge(id);assertEquals("deleted",from(b).download(latest(),"account","token").kind);assertEquals(0,b.list("").size());}
 public void testCorruptAttachmentCannotCreateHalfPointOrOverwriteLocal()throws Exception {String id=audio();from(a).upload(a.get(id),"account","token");String local=b.createText("本机","安全原文");remote.corrupt=true;try{from(b).download(latest(),"account","token");fail();}catch(IOException expected){}assertEquals(1,b.list("").size());assertEquals("安全原文",b.get(local).body);assertFalse(CloudRestore.seen(b,"account",id,latest().getString("manifest_hash")));}
 public void testIosPayloadAndUnknownFieldsSurviveDownloadAndReupload()throws Exception {String id=UUID.randomUUID().toString(),message=UUID.randomUUID().toString();JSONObject payload=new JSONObject().put("points",new JSONArray().put(new JSONObject().put("id",id.toUpperCase(Locale.ROOT)).put("head_revision",1).put("status","active"))).put("messages",new JSONArray().put(new JSONObject().put("id",message.toUpperCase(Locale.ROOT)).put("point_id",id).put("sequence",1).put("role","user").put("modality","text").put("user_text","来自 iOS 的文字"))).put("derivations",new JSONArray().put(new JSONObject().put("id",UUID.randomUUID().toString()).put("summary","iOS 摘要").put("private_future_field","保留内容"))).put("future_table",new JSONArray().put(new JSONObject().put("opaque","unknown")));JSONObject manifest=new JSONObject().put("format_version",1).put("point_id",id).put("revision",1).put("title","iOS 标题").put("preview","来自 iOS 的文字").put("created_at",1700000000).put("assets",new JSONArray()).put("payload",payload);remote.commit(manifest);from(b).download(latest(),"account","token");assertEquals("来自 iOS 的文字",b.get(id).body);assertEquals("iOS 摘要",b.get(id).summary);b.update(id,"修改标题","编辑后的文字");JSONObject next=from(b).snapshot(b.get(id));assertEquals("保留内容",next.getJSONObject("payload").getJSONArray("derivations").getJSONObject(0).getString("private_future_field"));assertEquals("unknown",next.getJSONObject("payload").getJSONArray("future_table").getJSONObject(0).getString("opaque"));assertEquals("编辑后的文字",next.getJSONObject("payload").getJSONArray("messages").getJSONObject(0).getString("user_text"));}
 public void testAccountChangeStopsBeforeNetworkOrImport()throws Exception {String id=a.createText("标题","正文");from(a).upload(a.get(id),"account","token");CloudSync sync=from(b).guarded(()->false);try{sync.downloadAll("account","token",p->{});fail();}catch(IOException expected){}assertEquals(0,b.list("").size());}
 public void testAccountsDoNotShareVersionMarkers()throws Exception {String id=a.createText("标题","正文");from(a).upload(a.get(id),"one","token");from(b).download(latest(),"one","token");assertEquals("conflict",from(b).download(latest(),"two","token").kind);assertEquals(2,b.list("").size());}
 public void testPayloadPointMismatchIsRejected()throws Exception {String id=a.createText("标题","正文");JSONObject m=from(a).snapshot(a.get(id));m.getJSONObject("payload").getJSONArray("points").getJSONObject(0).put("id",UUID.randomUUID().toString());remote.commit(m);try{from(b).download(latest(),"account","token");fail();}catch(IOException expected){}assertEquals(0,b.list("").size());}
 public void testBulkDownloadChoosesLatestVersionOnce()throws Exception {String id=a.createText("标题","旧版");from(a).upload(a.get(id),"account","token");a.update(id,"标题","最新版");from(a).upload(a.get(id),"account","token");CloudSync.Report result=from(b).downloadAll("account","token",p->{});assertEquals(1,result.added);assertEquals(0,result.conflicts);assertEquals("最新版",b.get(id).body);}
 public void testExplicitCopyCanRecoverDeletedPointWithoutResurrectingOriginal()throws Exception {String id=a.createText("标题","云端原文");from(a).upload(a.get(id),"account","token");from(b).download(latest(),"account","token");b.trash(id,true);b.purge(id);CloudRestore.Result r=from(b).download(latest(),"account","token",true);assertEquals("conflict",r.kind);assertFalse(id.equals(r.id));assertEquals("云端原文",b.get(r.id).body);assertEquals(1,b.list("").size());try{b.get(id);fail();}catch(IllegalStateException expected){}}
 public void testFailedImportRollsBackPointAndFiles()throws Exception {String id=a.createText("标题","正文");JSONObject m=from(a).snapshot(a.get(id));m.getJSONObject("payload").put("point_images",new JSONArray().put(new JSONObject().put("id",UUID.randomUUID().toString()).put("sha256","a".repeat(64))));remote.commit(m);try{from(b).download(latest(),"account","token");fail();}catch(IOException expected){}assertEquals(0,b.list("").size());}
 public void testConfirmedRelationsSurviveRoundTrip()throws Exception {String id=a.createText("源","正文"),other=a.createText("目标","正文");a.relation(id,other,"支持");from(a).upload(a.get(id),"account","token");from(b).download(latest(),"account","token");try(android.database.Cursor c=b.getReadableDatabase().rawQuery("SELECT type FROM relations WHERE source=? AND target=?",new String[]{id,other})){assertTrue(c.moveToFirst());assertEquals("支持",c.getString(0));}}

 public void testVersionEightMigrationKeepsPointAndClearsOldSnapshotCache()throws Exception {String id=a.createText("迁移记录","原文完整保留");a.cacheSnapshot(id,a.get(id).revision,"{}");a.getWritableDatabase().execSQL("DROP TABLE sync_sources");a.getWritableDatabase().execSQL("DROP TABLE sync_versions");a.getWritableDatabase().setVersion(8);a.close();a=new PointStore(getInstrumentation().getTargetContext(),an);assertEquals("原文完整保留",a.get(id).body);assertNull(a.snapshotCache(id,a.get(id).revision));assertTrue(from(a).upload(a.get(id),"account","token"));}

 public void testUnavailableHeadFallsBackToVerifiedUpload()throws Exception {String id=audio();remote.failHeads=1;from(a).upload(a.get(id),"account","token");assertEquals(1,remote.uploads);assertEquals(1,remote.versions.length());}
 public void testLostCommitResponseRetriesWithoutDuplicateCloudVersion()throws Exception {String id=a.createText("标题","正文");remote.loseCommit=true;assertTrue(from(a).upload(a.get(id),"account","token"));assertEquals(1,remote.versions.length());}
 public void testAccountChangeAfterDownloadCannotCommitAnotherAccountsData()throws Exception {String id=a.createText("标题","正文");from(a).upload(a.get(id),"account","token");java.util.concurrent.atomic.AtomicBoolean active=new java.util.concurrent.atomic.AtomicBoolean(true);remote.afterDownload=()->active.set(false);try{from(b).guarded(active::get).download(latest(),"account","token");fail();}catch(IOException expected){}assertEquals(0,b.list("").size());}

 public void testExtraIosAudioRemainsPlayableAndIncludedInReupload()throws Exception {String id=audio();JSONObject m=from(a).snapshot(a.get(id));JSONObject first=m.getJSONArray("assets").getJSONObject(0);remote.blobs.put(first.getString("sha256"),Files.readAllBytes(a.audioFile(a.get(id)).toPath()));String second=UUID.randomUUID().toString(),message=UUID.randomUUID().toString();m.getJSONArray("assets").put(new JSONObject(first.toString()).put("id",second));JSONObject payload=m.getJSONObject("payload");payload.getJSONArray("audio_assets").put(new JSONObject(payload.getJSONArray("audio_assets").getJSONObject(0).toString()).put("id",second).put("message_id",message));payload.getJSONArray("messages").put(new JSONObject().put("id",message).put("point_id",id).put("sequence",2).put("role","user").put("modality","voice").put("user_text",""));payload.getJSONArray("transcripts").put(new JSONObject().put("asset_id",second).put("engine_text","第二段原音转写"));remote.commit(m);from(b).download(latest(),"account","token");JSONArray extras=CloudSync.extraAudio(b,id);assertEquals(1,extras.length());assertEquals("第二段原音转写",extras.getJSONObject(0).getString("text"));assertTrue(new File(b.audio.getParentFile(),extras.getJSONObject(0).getString("path")).isFile());JSONObject uploaded=from(b).snapshot(b.get(id));assertEquals(2,uploaded.getJSONArray("assets").length());assertEquals(2,uploaded.getJSONObject("payload").getJSONArray("audio_assets").length());}
 public void testReplacedNativeAudioDoesNotReturnAsRecoveredDuplicate()throws Exception {String id=audio();File old=a.audioFile(a.get(id));from(a).upload(a.get(id),"account","token");JSONObject m=new JSONObject(new String(remote.manifests.get(latest().getString("manifest_hash")),StandardCharsets.UTF_8));byte[] bytes=Files.readAllBytes(old.toPath()),newBytes=Arrays.copyOf(bytes,bytes.length+1);String digest=CloudSync.hash(newBytes);remote.blobs.put(digest,newBytes);m.put("revision",m.getInt("revision")+1);m.getJSONObject("payload").getJSONArray("points").getJSONObject(0).put("head_revision",m.getInt("revision"));m.getJSONArray("assets").getJSONObject(0).put("sha256",digest).put("byte_count",newBytes.length);m.getJSONObject("payload").getJSONArray("audio_assets").getJSONObject(0).put("sha256",digest).put("byte_count",newBytes.length);remote.commit(m);assertEquals("updated",from(a).download(latest(),"account","token").kind);assertFalse(old.exists());assertEquals(0,a.recover());assertEquals(1,a.list("").size());assertEquals(digest,LocalSpeech.hash(a.audioFile(a.get(id))));}

}
